changeSet.sql:
-- Gouvernements des Régions et Communautés (fonction 89) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Membres des gouvernements régionaux et communautaires (Flandre, Wallonie, Fédération Wallonie-Bruxelles, Bruxelles-Capitale, Communauté germanophone)' WHERE c.country_iso = 'BE' AND f.id = 89 AND p.dataset_name = 'be_pep_regional_governments';
-- Ajout du lien be_pep_moniteur pour la fonction 89 INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Nominations et démissions des ministres régionaux publiées aux actes du Moniteur belge', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id JOIN parser p ON p.dataset_name = 'be_pep_moniteur' WHERE c.country_iso = 'BE' AND f.id = 89 ON DUPLICATE KEY UPDATE completeness = 'COMPLETE';
-- Parlement de la Région de Bruxelles-Capitale (fonction 96) UPDATE pep_function_parser pfp JOIN parser p ON p.id = pfp.parser_id JOIN pep_function f ON f.id = pfp.function_id JOIN pep_category c ON c.id = f.category_id SET pfp.completeness = 'COMPLETE', pfp.covered_scope = 'Députés régionaux bruxellois et élus francophones siégeant aux assemblées bruxelloises' WHERE c.country_iso = 'BE' AND f.id = 96 AND p.dataset_name = 'be_pep_regional_parliaments';
